# ===========================================================================
# Module A: AMETHYST fair-value market making (official fair value 10,000)
# verbatim copy of research/A/strategy.py (sha256 11b1c9b4f11bada1)
# ===========================================================================
def _build_module_A():
    """Direction A: fair-value market making with optional inventory control.

    Per traded product, every tick:
      1. (optional) fair value FV: an official/EDA constant, a causal EMA of the
         mid stored in traderData, or none.
      2. (optional, needs FV) take every visible quote strictly through FV.
      3. passive quotes: join the touch (`improve`=0) or step inside it, then an
         optional inventory skew, then (if FV) cap bid <= FV-edge, ask >= FV+edge.
      4. sizes: whatever is left of a soft position cap (cap_frac * official limit),
         so worst-case buys and worst-case sells each stay inside the limit.

    Constants and their evidence:
      AMETHYST 10000      official example_trader_3.py ("constant fair value of 10,000")
      GOLDEN_PEARLS 8000  day -2 EDA only (mid in [7999.5, 8000.5] on all 10,000 ticks,
                          research/A/results/eda_day-2.txt); NOT an official value.
      LIMITS              official Wiki Products tab (copied from core/common.py).

    Imports: datamodel + standard library only.
    """
    import json
    import math

    from datamodel import Order, OrderDepth, TradingState  # noqa: F401  (OrderDepth/TradingState for typing)

    LIMITS = {
        'AMETHYST': 50, 'TOFFEE_CAKE': 50, 'PAPER_LANTERNS': 50, 'TELLURIUM': 40,
        'JELLY': 50, 'PEANUT_BUTTER': 50, 'DRAGONFRUIT': 40, 'GRANADILLA': 40,
        'MANGOSTEEN': 40, 'FRUIT_BASKET': 40, 'LYCHEE': 200,
        'WHITE_PEARLS': 20, 'BLACK_PEARLS': 20, 'GOLDEN_PEARLS': 20,
        'PINK_PEARLS': 20, 'BLUE_PEARLS': 20,
    }
    LIMITS.update({f'VOUCHER_{k}': 50 for k in (6800, 7000, 7200, 7300, 7400, 7500, 7600, 7750, 7900, 8100)})

    FV_CONST = {'AMETHYST': 10000, 'GOLDEN_PEARLS': 8000}

    # Products the DEFAULT (nominee) configuration may trade; it reads no others.
    PRODUCTS = ('AMETHYST',)

    DEFAULTS = {
        # Final nominee = registered config h1_take_join restricted to AMETHYST (official FV 10000).
        # GOLDEN_PEARLS failed the day -1 gate (peg broke: day -1 end mid 7899.5); see REPORT.md.
        'trade': list(PRODUCTS),
        'fv': 'const',          # 'const' (FV_CONST, else none) | 'ema' | 'none'
        'ema_alpha': 0.05,      # weight of the newest mid in the causal EMA
        'take': True,           # take visible quotes strictly through FV (needs FV)
        'edge': 1,              # passive bid <= FV - edge, ask >= FV + edge (needs FV); >= 1
        'improve': 0,           # ticks inside the touch; 0 = join best bid / best ask
        'cap_frac': 1.0,        # soft cap = floor(cap_frac * official limit)
        'skew_at': None,        # |pos| >= skew_at * limit -> skew both quotes by skew_ticks
        'skew_ticks': 1,
        'per_product': {},      # per-product overrides of the keys above
    }

    _KEYS = ('fv', 'ema_alpha', 'take', 'edge', 'improve', 'cap_frac', 'skew_at', 'skew_ticks')


    def _memory(raw):
        try:
            obj = json.loads(raw) if isinstance(raw, str) and raw else {}
        except (ValueError, TypeError):
            return {}
        return obj if isinstance(obj, dict) else {}


    def _touch(depth):
        """(best_bid, best_ask, bids desc [(p, v)], asks asc [(p, v)]) or None."""
        try:
            if depth is None or not depth.buy_orders or not depth.sell_orders:
                return None
            bids = sorted(((int(p), int(v)) for p, v in depth.buy_orders.items() if int(v) > 0), reverse=True)
            asks = sorted((int(p), -int(v)) for p, v in depth.sell_orders.items() if int(v) < 0)
        except (AttributeError, TypeError, ValueError):
            return None
        if not bids or not asks or bids[0][0] >= asks[0][0]:
            return None
        return bids[0][0], asks[0][0], bids, asks


    class Trader:
        def __init__(self, config=None):
            self.cfg = {**DEFAULTS, **(config or {})}   # registered configs list every key

        def _params(self, product):
            p = {k: self.cfg[k] for k in _KEYS}
            p.update(self.cfg.get('per_product', {}).get(product, {}))
            return p

        def run(self, state):
            mem = _memory(state.traderData)
            ema_mem = mem.get('e') if isinstance(mem.get('e'), dict) else {}
            new_ema = {}
            orders = {}
            for product in self.cfg['trade']:
                if product not in LIMITS:
                    continue
                prm = self._params(product)
                top = _touch(state.order_depths.get(product))
                if prm['fv'] == 'ema':
                    old = ema_mem.get(product)
                    if not isinstance(old, (int, float)) or isinstance(old, bool) or not math.isfinite(old):
                        old = None
                    if top is None:
                        if old is not None:
                            new_ema[product] = old
                        continue
                    mid = (top[0] + top[1]) / 2
                    a = float(prm['ema_alpha'])
                    ema = mid if old is None else a * mid + (1 - a) * old
                    new_ema[product] = ema
                    fv = math.floor(ema + 0.5)
                elif prm['fv'] == 'const':
                    fv = FV_CONST.get(product)
                else:
                    fv = None
                if top is None:
                    continue
                pos = state.position.get(product, 0) if isinstance(state.position, dict) else 0
                out = self._quote(product, top, int(pos), fv, prm)
                if out:
                    orders[product] = out
            out_mem = {'e': new_ema} if new_ema else {}     # only our own keys survive
            return orders, 0, json.dumps(out_mem, separators=(',', ':'))

        @staticmethod
        def _quote(product, top, pos, fv, prm):
            bb, ba, bids, asks = top
            lim = LIMITS[product]
            cap = max(0, min(lim, int(math.floor(float(prm['cap_frac']) * lim))))
            buy_left = max(0, min(cap - pos, lim - pos))
            sell_left = max(0, min(cap + pos, lim + pos))
            edge = max(1, int(prm['edge']))
            out = []
            if fv is not None and prm['take']:
                for px, vol in asks:                 # buy anything offered below FV
                    if px >= fv or buy_left <= 0:
                        break
                    q = min(vol, buy_left)
                    out.append(Order(product, int(px), int(q)))
                    buy_left -= q
                for px, vol in bids:                 # sell into anything bid above FV
                    if px <= fv or sell_left <= 0:
                        break
                    q = min(vol, sell_left)
                    out.append(Order(product, int(px), -int(q)))
                    sell_left -= q
            imp = int(prm['improve'])
            bid, ask = bb + imp, ba - imp
            if bid >= ask:                           # stepping inside would cross: join instead
                bid, ask = bb, ba
            if prm['skew_at'] is not None:
                thr = float(prm['skew_at']) * lim
                k = int(prm['skew_ticks'])
                if pos >= thr and pos > 0:           # long: back off the bid, lean on the ask
                    bid -= k
                    ask = max(ask - k, bb + 1)
                elif pos <= -thr and pos < 0:        # short: mirror
                    ask += k
                    bid = min(bid + k, ba - 1)
            if fv is not None:
                bid = min(bid, fv - edge)
                ask = max(ask, fv + edge)
            bid = min(bid, ba - 1)                   # passive only
            ask = max(ask, bb + 1)
            if bid >= ask or bid <= 0:
                return out
            if buy_left > 0:
                out.append(Order(product, int(bid), int(buy_left)))
            if sell_left > 0:
                out.append(Order(product, int(ask), -int(sell_left)))
            return out

    return Trader


ModuleA = _build_module_A()


# ===========================================================================
# Module D: Slow mean reversion (anchor-deviation z band, take-only)
# verbatim copy of research/D/strategy.py (sha256 a56fab7372a95e33)
# ===========================================================================
def _build_module_D():
    """Direction D: mean reversion against a causal anchor.

    Two leg types, configured per product (config['legs'][symbol]):

      mode 'band'  z-score band reversion. anchor = EMA(mid) (prior value), dev =
                   mid - anchor, z = dev / EWMA-std(dev). Enter (target +/-size)
                   when |z| >= entry, close when z crosses exit_z back toward the
                   anchor. exec: 'take' (cross at best level, volume-capped),
                   'passive' (quote at touch [+improve] toward target), 'hybrid'
                   (take entries, passive exits). flip=True is the momentum control
                   with identical timing/turnover.
      mode 'mm'    market making: quote both sides at the touch (+improve), capped
                   to stay at least min_edge away from fair - skew*position, where
                   fair = EMA(mid incl. current) with half-life fair_hl. fair_hl=None
                   is the neutral touch-join baseline (official example 1 logic).

    Only datamodel + standard library. All state lives in traderData (small JSON).
    Every quantity used at tick t is computed from state at t and earlier ticks.
    """
    import json
    import math

    from datamodel import Order, OrderDepth, TradingState  # noqa: F401

    # Official Wiki position limits (core/common.py, read 2026-10-27).
    LIMITS = {'TOFFEE_CAKE': 50, 'PAPER_LANTERNS': 50, 'PINK_PEARLS': 20, 'LYCHEE': 200,
              'VOUCHER_7500': 50, 'VOUCHER_7600': 50, 'VOUCHER_7750': 50}
    # Products any registered experiment may trade (scope checks included).
    RESEARCH_PRODUCTS = tuple(sorted(LIMITS))

    BAND_DEFAULTS = {'mode': 'band', 'anchor_hl': 500.0, 'sd_hl': 1000.0, 'warmup': 300,
                     'entry': 2.0, 'exit_z': 0.0, 'size': 50, 'exec': 'take', 'improve': 0,
                     'flip': False, 'max_hold': None}
    MM_DEFAULTS = {'mode': 'mm', 'fair_hl': None, 'min_edge': 1.0, 'improve': 0, 'skew': 0.0,
                   'size': 50, 'take_edge': None}

    # Nominee configuration (set after the registered selection; see candidate.json).
    # Selected by the preregistered rule (results/selection.json): TOFFEE_CAKE leg =
    # h1r2_hl500_z1.5_hold1000 (H1, round 2), PAPER_LANTERNS leg = h3_fv_hl2 (H3, round 1).
    DEFAULTS = {'legs': {
        'TOFFEE_CAKE': {'mode': 'band', 'anchor_hl': 500, 'entry': 1.5, 'exit_z': 0.0,
                        'exec': 'take', 'max_hold': 1000},
        'PAPER_LANTERNS': {'mode': 'mm', 'fair_hl': 2, 'min_edge': 1.0, 'improve': 0,
                           'skew': 0.0, 'size': 50}}}
    PRODUCTS = ('PAPER_LANTERNS', 'TOFFEE_CAKE')   # products the DEFAULT config may trade


    def _num(x):
        """Finite float or None (rejects bool/str/NaN/inf from corrupted memory)."""
        if isinstance(x, bool) or not isinstance(x, (int, float)):
            return None
        x = float(x)
        return x if math.isfinite(x) else None


    def _load(raw):
        try:
            obj = json.loads(raw) if isinstance(raw, str) and raw else {}
        except (ValueError, TypeError):
            return {}
        return obj if isinstance(obj, dict) else {}


    def _top(book):
        """(bb, ba, bid_vol, ask_vol) or None for a missing / one-sided / crossed book."""
        try:
            if book is None or not book.buy_orders or not book.sell_orders:
                return None
            bb, ba = max(book.buy_orders), min(book.sell_orders)
            bv, av = book.buy_orders[bb], -book.sell_orders[ba]
            if type(bb) is not int or type(ba) is not int or bb >= ba or bv <= 0 or av <= 0:
                return None
            return bb, ba, int(bv), int(av)
        except (AttributeError, TypeError, ValueError):
            return None


    def _alpha(hl):
        return 1.0 - 0.5 ** (1.0 / float(hl))


    class Trader:
        def __init__(self, config=None):
            cfg = dict(DEFAULTS)
            cfg.update(config or {})
            legs = {}
            for sym, leg in (cfg.get('legs') or {}).items():
                base = BAND_DEFAULTS if leg.get('mode', 'band') == 'band' else MM_DEFAULTS
                legs[sym] = {**base, **leg}
            self.legs = legs

        # ------------------------------------------------------------------ run
        def run(self, state):
            mem = _load(state.traderData)
            out_mem, orders = {}, {}
            for sym, leg in self.legs.items():
                if sym not in LIMITS:
                    continue
                m = mem.get(sym)
                m = m if isinstance(m, dict) else {}
                tob = _top(state.order_depths.get(sym))
                if tob is None:              # no usable book: keep memory, no orders
                    if m:
                        out_mem[sym] = m
                    continue
                pos = state.position.get(sym, 0)
                pos = pos if type(pos) is int else 0
                if leg['mode'] == 'band':
                    o, m = self._band(sym, leg, tob, pos, m)
                else:
                    o, m = self._mm(sym, leg, tob, pos, m, state.order_depths[sym])
                out_mem[sym] = m
                if o:
                    orders[sym] = o
            return orders, 0, json.dumps(out_mem, separators=(',', ':'))

        # ----------------------------------------------------------------- band
        def _band(self, sym, leg, tob, pos, m):
            bb, ba, bv, av = tob
            lim = LIMITS[sym]
            mid = (bb + ba) / 2.0
            a, v = _num(m.get('a')), _num(m.get('v'))
            n = m.get('n') if type(m.get('n')) is int else 0
            s = m.get('s') if m.get('s') in (-1, 0, 1) and type(m.get('s')) is int else 0
            if a is None:
                a, v, n, s = mid, None, 0, 0
            dev = mid - a                           # deviation from the PRIOR anchor
            z = dev / math.sqrt(v) if (v is not None and v > 0 and n >= int(leg['warmup'])) else None
            v = dev * dev if v is None else v + _alpha(leg['sd_hl']) * (dev * dev - v)
            a = a + _alpha(leg['anchor_hl']) * (mid - a)
            n = min(n + 1, 10 ** 9)
            entry, ex = float(leg['entry']), float(leg['exit_z'])
            mh = leg.get('max_hold')
            h = m.get('h') if type(m.get('h')) is int and m.get('h') >= 0 else 0
            b = m.get('b') if m.get('b') in (-1, 0, 1) and type(m.get('b')) is int else 0
            if z is not None:
                prev = s
                if (b == 1 and z >= ex) or (b == -1 and z <= -ex):
                    b = 0                           # stopped side re-armed once back at anchor
                if z <= -entry and b != 1:
                    s = 1
                elif z >= entry and b != -1:
                    s = -1
                elif s == 1 and z >= ex:
                    s = 0
                elif s == -1 and z <= -ex:
                    s = 0
                h = h + 1 if (s != 0 and s == prev) else (1 if s != 0 else 0)
                if mh is not None and s != 0 and h > int(mh):
                    b, s, h = s, 0, 0               # time stop: flatten, block that side
            new_m = {'a': round(a, 4), 'v': round(v, 4), 'n': n, 's': s}
            if mh is not None:
                new_m.update(h=h, b=b)
            if z is None:                           # warm-up / reset: hold, no orders
                return [], new_m
            size = max(0, min(int(leg['size']), lim))
            target = s * size * (-1 if leg['flip'] else 1)
            delta = target - pos
            if delta == 0:
                return [], new_m
            ex_mode, imp = leg['exec'], max(0, int(leg['improve']))
            if delta > 0:
                take = ex_mode == 'take' or (ex_mode == 'hybrid' and target > 0 and pos >= 0)
                if take:
                    q = min(delta, av, lim - pos)
                    return ([Order(sym, ba, q)] if q > 0 else []), new_m
                px = bb + imp if bb + imp < ba else bb
                q = min(delta, lim - pos)
                return ([Order(sym, px, q)] if q > 0 else []), new_m
            take = ex_mode == 'take' or (ex_mode == 'hybrid' and target < 0 and pos <= 0)
            if take:
                q = min(-delta, bv, lim + pos)
                return ([Order(sym, bb, -q)] if q > 0 else []), new_m
            px = ba - imp if ba - imp > bb else ba
            q = min(-delta, lim + pos)
            return ([Order(sym, px, -q)] if q > 0 else []), new_m

        # ------------------------------------------------------------------- mm
        def _mm(self, sym, leg, tob, pos, m, book):
            bb, ba, _, _ = tob
            lim = LIMITS[sym]
            mid = (bb + ba) / 2.0
            new_m = {}
            fa = None
            if leg['fair_hl'] is not None:
                f = _num(m.get('f'))
                f = mid if f is None else f + _alpha(leg['fair_hl']) * (mid - f)
                new_m['f'] = round(f, 4)
                fa = f - float(leg['skew']) * pos
            imp = max(0, int(leg['improve']))
            bid_px = bb + imp if bb + imp < ba else bb
            ask_px = ba - imp if ba - imp > bb else ba
            if bid_px >= ask_px:
                bid_px, ask_px = bb, ba
            size = max(0, min(int(leg['size']), lim))
            buy_cap, sell_cap = min(size, lim - pos), min(size, lim + pos)
            buys, sells = [], []
            if fa is not None:
                e = max(0.0, float(leg['min_edge']))
                bid_px = min(bid_px, math.floor(fa - e))
                ask_px = max(ask_px, math.ceil(fa + e))
                te = leg['take_edge']
                if te is not None:
                    for px in sorted(book.sell_orders):
                        if px > fa - float(te) or buy_cap <= 0:
                            break
                        q = min(-book.sell_orders[px], buy_cap)
                        if q > 0:
                            buys.append(Order(sym, int(px), int(q)))
                            buy_cap -= q
                    for px in sorted(book.buy_orders, reverse=True):
                        if px < fa + float(te) or sell_cap <= 0:
                            break
                        q = min(book.buy_orders[px], sell_cap)
                        if q > 0:
                            sells.append(Order(sym, int(px), -int(q)))
                            sell_cap -= q
            if buy_cap > 0 and bid_px > 0:
                buys.append(Order(sym, int(bid_px), int(buy_cap)))
            if sell_cap > 0 and ask_px > 0:
                sells.append(Order(sym, int(ask_px), -int(sell_cap)))
            if buys and sells and max(o.price for o in buys) >= min(o.price for o in sells):
                sells = [o for o in sells if o.price > max(b.price for b in buys)]
            return buys + sells, new_m

    return Trader


ModuleD = _build_module_D()


