# Module E: Slow mean reversion (EWMA z-score band, take-only)
# verbatim copy of research/E/strategy.py (sha256 a05aa4331ac11681)
# ===========================================================================
def _build_module_E():
    """Direction E: statistical pair / basket relative-value module (take-only legs).

    There is NO conversion, creation or redemption in QuantiFi 2026 and the
    FRUIT_BASKET weights are NOT published, so nothing forces convergence. This
    module only bets that a hedged spread reverts to its own slowly moving mean.

    Spread  s_t = s_{t-1} + sum_i c_i * (mid_i,t - mid_i,t-1)   (anchor c = 1)
            (with fixed c this is the level spread sum_i c_i * mid_i + const)
    Signal  z_t = (s_t - mu_{t-1}) / sd_{t-1}, EWMA mean/variance, half-life hl
            ticks, updated after z is formed (strictly past statistics).
    Target  z > z_in -> -max_pkgs ; z < -z_in -> +max_pkgs ; |z| < z_out -> 0 ;
            otherwise keep the previous target (hysteresis).
    Orders  take-only at level 1 with size <= visible level-1 volume (no residual
            can rest, so fills do not depend on the passive-fill model). The
            anchor moves k packages only if every hedge leg can trade its
            matching amount at level 1 within its limit in the same tick; each
            hedge leg is moved toward round(c_i * anchor_position) every tick,
            which repairs any imbalance left by a leg that did not trade.

    Coefficients in PAIRS are DAY -2 OLS estimates of mid changes (see
    research/E/results/eda_day-2.txt section 3 and eda5_day-2.txt), applied
    unchanged to other days. They are NOT the official basket composition.
    hedge='causal' replaces them by an exponentially weighted OLS estimated from
    ticks <= t-1 only.

    Only `datamodel` and the standard library are imported.
    """
    import json
    import math

    from datamodel import Order, OrderDepth, TradingState  # noqa: F401

    LIMITS = {'FRUIT_BASKET': 40, 'DRAGONFRUIT': 40, 'GRANADILLA': 40, 'MANGOSTEEN': 40,
              'WHITE_PEARLS': 20, 'BLACK_PEARLS': 20, 'JELLY': 50, 'PEANUT_BUTTER': 50}

    # (product, fixed coefficient); anchor first. Day -2 estimates, not official.
    PAIRS = {
        'basket': (('FRUIT_BASKET', 1.0), ('DRAGONFRUIT', -2.0), ('GRANADILLA', -3.0),
                   ('MANGOSTEEN', -1.0)),
        'pearls': (('WHITE_PEARLS', 1.0), ('BLACK_PEARLS', 0.70)),
        'jelly_pb': (('JELLY', 1.0), ('PEANUT_BUTTER', -0.40)),
        # round-2 attribution control only (single leg, own-price signal); added after round 1,
        # does not change the code path of the pairs above.
        'jelly': (('JELLY', 1.0),),
    }
    PRODUCTS = tuple(sorted({p for legs in PAIRS.values() for p, _ in legs}))

    DEFAULTS = {'pair': 'basket', 'hedge': 'fixed', 'hl': 1000, 'z_in': 2.0, 'z_out': 0.5,
                'warmup': 1000, 'max_pkgs': 13, 'beta_hl': 2000, 'beta_burn': 200}


    def _num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool) and math.isfinite(x)


    def _bba(depth):
        """(best_bid, bid_vol, best_ask, ask_vol) or None; never raises."""
        try:
            if depth is None or not depth.buy_orders or not depth.sell_orders:
                return None
            b = max(depth.buy_orders)
            a = min(depth.sell_orders)
            bv = int(depth.buy_orders[b])
            av = -int(depth.sell_orders[a])
            if b >= a or bv <= 0 or av <= 0:
                return None
            return int(b), bv, int(a), av
        except (AttributeError, TypeError, ValueError):
            return None


    def _rnd(x):
        """Round half away from zero (symmetric for long and short packages)."""
        return int(math.copysign(math.floor(abs(x) + 0.5), x))


    def _solve(a, b):
        """Solve a small dense system a x = b (Gaussian elimination). None if singular."""
        n = len(b)
        m = [list(a[i]) + [b[i]] for i in range(n)]
        for c in range(n):
            p = max(range(c, n), key=lambda r: abs(m[r][c]))
            if abs(m[p][c]) < 1e-12:
                return None
            m[c], m[p] = m[p], m[c]
            for r in range(n):
                if r != c:
                    f = m[r][c] / m[c][c]
                    for k in range(c, n + 1):
                        m[r][k] -= f * m[c][k]
        return [m[i][n] / m[i][i] for i in range(n)]


    class Trader:
        def __init__(self, config=None):
            self.cfg = {**DEFAULTS, **(config or {})}

        # ---------------------------------------------------------------- memory
        def _load(self, raw, k):
            try:
                mem = json.loads(raw) if isinstance(raw, str) and raw else {}
            except (ValueError, TypeError):
                mem = {}
            if not isinstance(mem, dict) or mem.get('pair') != self.cfg['pair']:
                return {}
            ok = (isinstance(mem.get('pm'), list) and len(mem['pm']) == k and all(_num(v) for v in mem['pm'])
                  and isinstance(mem.get('c'), list) and len(mem['c']) == k and all(_num(v) for v in mem['c'])
                  and all(_num(mem.get(f)) for f in ('s', 'mu', 'v', 'n', 'T', 'nr')) and mem['v'] >= 0)
            if ok and self.cfg['hedge'] == 'causal':
                h = k - 1
                ok = (isinstance(mem.get('xx'), list) and len(mem['xx']) == h * h and all(_num(v) for v in mem['xx'])
                      and isinstance(mem.get('xy'), list) and len(mem['xy']) == h and all(_num(v) for v in mem['xy']))
            return mem if ok else {}

        def _fresh(self, legs, mids):
            cfg = self.cfg
            k = len(legs)
            if cfg['hedge'] == 'causal':
                c = [1.0] + [0.0] * (k - 1)
            else:
                c = [float(x) for _, x in legs]
            mem = {'pair': cfg['pair'], 'pm': mids, 'c': c, 's': 0.0, 'mu': 0.0, 'v': 0.0,
                   'n': 0, 'T': 0, 'nr': 0}
            if cfg['hedge'] == 'causal':
                mem['xx'] = [0.0] * ((k - 1) ** 2)
                mem['xy'] = [0.0] * (k - 1)
            return mem

        # ---------------------------------------------------------------- signal
        def _update(self, mem, mids):
            """Advance spread/EWMA/regression by one tick; return z (or None)."""
            cfg = self.cfg
            k = len(mids)
            d = [mids[i] - mem['pm'][i] for i in range(k)]
            mem['pm'] = mids
            causal = cfg['hedge'] == 'causal'
            z = None
            if (not causal) or mem['nr'] >= cfg['beta_burn']:
                ds = sum(mem['c'][i] * d[i] for i in range(k))
                s = mem['s'] + ds
                mu, v, n = mem['mu'], mem['v'], int(mem['n']) + 1
                if n > cfg['warmup'] and v > 0:
                    z = (s - mu) / math.sqrt(v)
                a = 1.0 - 0.5 ** (1.0 / cfg['hl'])
                e = s - mu
                mem['mu'] = mu + a * e
                mem['v'] = (1.0 - a) * (v + a * e * e)
                mem['s'], mem['n'] = s, n
            if causal:
                # EW-OLS of anchor change on hedge-leg changes; used from the NEXT tick on.
                lam = 0.5 ** (1.0 / cfg['beta_hl'])
                h = k - 1
                x, y = d[1:], d[0]
                xx = [lam * mem['xx'][i * h + j] + x[i] * x[j] for i in range(h) for j in range(h)]
                xy = [lam * mem['xy'][i] + x[i] * y for i in range(h)]
                mem['xx'], mem['xy'] = xx, xy
                mem['nr'] = int(mem['nr']) + 1
                if mem['nr'] >= cfg['beta_burn']:
                    tr = sum(xx[i * h + i] for i in range(h))
                    ridge = 1e-9 * tr + 1e-12
                    beta = _solve([[xx[i * h + j] + (ridge if i == j else 0.0) for j in range(h)]
                                   for i in range(h)], xy)
                    if beta is not None and all(math.isfinite(b) for b in beta):
                        mem['c'] = [1.0] + [-b for b in beta]
            return z

        # ------------------------------------------------------------- execution
        def _execute(self, names, coefs, books, pos, target):
            cfg = self.cfg
            hedged = cfg['hedge'] != 'none'
            anchor = names[0]
            cur = pos[anchor]
            lim_a = LIMITS[anchor]

            def leg_target(i, packages):
                lim = LIMITS[names[i]]
                return max(-lim, min(lim, _rnd(coefs[i] * packages)))

            def can_trade(p, q):
                if q == 0:
                    return True
                b = books[p]
                if b is None or abs(pos[p] + q) > LIMITS[p]:
                    return False
                return q <= b[3] if q > 0 else -q <= b[1]

            new = cur
            diff = target - cur
            if diff:
                step = 1 if diff > 0 else -1
                for kk in range(abs(diff), 0, -1):
                    cand = cur + step * kk
                    if abs(cand) > lim_a or not can_trade(anchor, cand - cur):
                        continue
                    if hedged and not all(can_trade(names[i], leg_target(i, cand) - pos[names[i]])
                                          for i in range(1, len(names))):
                        continue
                    new = cand
                    break
            orders = {}

            def send(p, q):
                b = books[p]
                if b is None or q == 0:
                    return
                if q > 0:
                    q = min(q, b[3], LIMITS[p] - pos[p])
                    if q > 0:
                        orders[p] = [Order(p, int(b[2]), int(q))]
                else:
                    q = -min(-q, b[1], LIMITS[p] + pos[p])
                    if q < 0:
                        orders[p] = [Order(p, int(b[0]), int(q))]

            send(anchor, new - cur)
            if hedged:
                for i in range(1, len(names)):
                    p = names[i]
                    send(p, leg_target(i, new) - pos[p])     # partial repair allowed
            return orders

        # ------------------------------------------------------------------- run
        def run(self, state):
            cfg = self.cfg
            legs = PAIRS[cfg['pair']]
            names = [p for p, _ in legs]
            k = len(names)
            depths = getattr(state, 'order_depths', None) or {}
            books = {p: _bba(depths.get(p)) for p in names}
            raw_pos = getattr(state, 'position', None) or {}
            pos = {}
            for p in names:
                try:
                    pos[p] = int(raw_pos.get(p, 0))
                except (TypeError, ValueError):
                    pos[p] = 0
            mem = self._load(getattr(state, 'traderData', ''), k)
            if all(books[p] is not None for p in names):
                mids = [(books[p][0] + books[p][2]) / 2.0 for p in names]
                if not mem:
                    mem = self._fresh(legs, mids)
                else:
                    z = self._update(mem, mids)
                    if z is not None:
                        if z > cfg['z_in']:
                            mem['T'] = -cfg['max_pkgs']
                        elif z < -cfg['z_in']:
                            mem['T'] = cfg['max_pkgs']
                        elif abs(z) < cfg['z_out']:
                            mem['T'] = 0
            target = int(mem.get('T', 0)) if mem else 0
            coefs = mem['c'] if mem else [float(c) for _, c in legs]
            orders = self._execute(names, coefs, books, pos, target)
            return orders, 0, json.dumps(mem, separators=(',', ':')) if mem else ''

    return Trader


