"""Module dispatcher shared by integration/composite.py and the generated submission.

Only `datamodel` and the standard library are used; the build script copies
this file verbatim into the single-file submission.

For each module (name, TraderClass, config, owned_products):
  * the module sees the portal state via _StateView (same order_depths/etc.,
    traderData replaced by its own memory slice); a slice that is not a string, is larger than
    MAX_MODULE_MEMORY, or is not parseable JSON is reset to '' (cold start);
  * only orders for products the module owns are kept (ownership is disjoint);
  * orders must have int price > 0 and int quantity != 0, else they are dropped;
  * if a product's buys (or sells) could breach the official limit in the
    worst case, all of that product's orders are dropped for the tick;
  * a module that raises keeps its memory and loses its orders for the tick.
Guard activations are counted in memory['_diag'] (name or guard -> count).
"""
import json


LIMITS = {'AMETHYST': 50, 'TOFFEE_CAKE': 50, 'PAPER_LANTERNS': 50, 'TELLURIUM': 40,
          'JELLY': 50, 'PEANUT_BUTTER': 50, 'DRAGONFRUIT': 40, 'GRANADILLA': 40,
          'MANGOSTEEN': 40, 'FRUIT_BASKET': 40, 'LYCHEE': 200, 'WHITE_PEARLS': 20,
          'BLACK_PEARLS': 20, 'GOLDEN_PEARLS': 20, 'PINK_PEARLS': 20, 'BLUE_PEARLS': 20,
          **{f'VOUCHER_{k}': 50 for k in (6800, 7000, 7200, 7300, 7400, 7500, 7600, 7750, 7900, 8100)}}
MAX_MODULE_MEMORY = 20_000


def _load_memory(raw):
    try:
        mem = json.loads(raw) if isinstance(raw, str) and raw else {}
    except (ValueError, TypeError, RecursionError):
        return {}
    return mem if isinstance(mem, dict) else {}


def _module_memory(raw):
    if not isinstance(raw, str) or len(raw) > MAX_MODULE_MEMORY:
        return ''
    if raw:
        try:
            json.loads(raw)
        except (ValueError, TypeError, RecursionError):
            return ''
    return raw


class _StateView:
    """Pass-through of portal TradingState; only override traderData.

    Do NOT reconstruct TradingState/OrderDepth — portal types may not match
    the local dataclass constructors, and a rebuild that raises is swallowed
    below into a silent no-op (portal PnL 0).
    """

    __slots__ = ('_state', 'traderData')

    def __init__(self, state, memory):
        object.__setattr__(self, '_state', state)
        object.__setattr__(self, 'traderData', memory)

    def __getattr__(self, name):
        return getattr(object.__getattribute__(self, '_state'), name)


def _module_state(state, memory):
    return _StateView(state, memory)


def _valid_orders(product, orders):
    return [o for o in orders
            if getattr(o, 'symbol', None) == product and type(getattr(o, 'price', None)) is int
            and type(getattr(o, 'quantity', None)) is int and o.price > 0 and o.quantity != 0]


def _within_limit(product, orders, position):
    limit = LIMITS.get(product)
    if limit is None:
        return False
    buys = sum(o.quantity for o in orders if o.quantity > 0)
    sells = -sum(o.quantity for o in orders if o.quantity < 0)
    return position + buys <= limit and position - sells >= -limit


def dispatch(modules, state):
    memory = _load_memory(state.traderData)
    raw_diag = memory.get('_diag')
    diag = {k: v for k, v in raw_diag.items() if type(v) is int} if isinstance(raw_diag, dict) else {}
    orders, new_memory = {}, {}

    def count(key):
        diag[key] = diag.get(key, 0) + 1

    for name, module, config, owned in modules:
        sub = memory.get(name, '')
        clean = _module_memory(sub)
        if clean != sub:
            count(f'{name}:memory_reset')
        try:
            result, _, sub_new = module(config).run(_module_state(state, clean))
        except Exception as e:
            new_memory[name] = clean
            count(name)
            count(f'{name}:{type(e).__name__}')
            continue
        new_memory[name] = sub_new if isinstance(sub_new, str) else ''
        if not isinstance(result, dict):
            continue
        for product, product_orders in result.items():
            if product not in owned or not isinstance(product_orders, list) or not product_orders:
                continue
            kept = _valid_orders(product, product_orders)
            if len(kept) != len(product_orders):
                count(f'{product}:invalid_order')
            position = state.position.get(product, 0)
            if kept and not _within_limit(product, kept, position if type(position) is int else 0):
                count(f'{product}:limit_guard')
                continue
            if kept:
                orders[product] = kept
    if diag:
        new_memory['_diag'] = diag
    return orders, 0, json.dumps(new_memory, separators=(',', ':'))


